import { rmSync, writeFileSync } from "node:fs";

import { expect, expectStatus, sample, test, uniqueName } from "../../fixtures";

test("An expired insurance certificate cannot be approved", { tag: "@REV-07" }, async ({ apiAs, factory }) => {
  // Arrange
  const reviewer = await apiAs("reviewer");
  const dayMs = 24 * 60 * 60 * 1000;
  const yesterdayLocal = new Date(Date.now() - dayMs);
  // Take the earlier of the UTC and local "yesterday" so the date is in the past whichever clock the API uses.
  const expiry = [
    new Date(Date.now() - dayMs).toISOString().slice(0, 10),
    `${yesterdayLocal.getFullYear()}-${String(yesterdayLocal.getMonth() + 1).padStart(2, "0")}-${String(yesterdayLocal.getDate()).padStart(2, "0")}`,
  ].sort()[0];
  const fileName = `${uniqueName("insurance-expired").replace(/\s+/g, "-")}.txt`;
  writeFileSync(
    sample(fileName),
    `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${expiry}\n`,
  );
  let arranged: Awaited<ReturnType<typeof factory.vendorInReview>>;
  try {
    arranged = await factory.vendorInReview({ files: { insurance_certificate: fileName } });
  } finally {
    rmSync(sample(fileName), { force: true });
  }
  const { documents, extractions } = arranged;

  // Act
  const response = await reviewer.post(`/api/extractions/${extractions.insurance_certificate.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("insurance_expired");
  expect((await factory.extraction(documents.insurance_certificate.id, "reviewer")).status).toBe("pending_review");
});
